/**
 * Photo validation and sanitising.
 *
 * The server never trusts the client's check: the bytes are decoded for real,
 * measured, and re-encoded from raw pixels. Because the output is built from
 * pixels only, EXIF - including GPS - cannot survive, which is the point
 * (MEDIA-01, MEDIA-02, AT-13).
 */
import { decode, encode } from 'jpeg-js'
import { AppError } from '../errors.js'

export interface ImageLimits {
  /** Largest accepted upload in bytes. */
  maxBytes: number
  /** Longest edge accepted on input, and the cap for the sanitised output. */
  maxLongEdge: number
  /** Total pixels accepted, expressed in hundredths of a megapixel. */
  maxMegapixelsX100: number
  /** Size we aim for after re-encoding. */
  targetBytes: number
  /** Longest edge of the generated thumbnail. */
  thumbLongEdge: number
}

export interface SanitisedImage {
  full: Uint8Array
  thumb: Uint8Array
  width: number
  height: number
  /** Quality the full image settled on, recorded for diagnostics. */
  quality: number
}

/** JPEG start-of-image marker. */
const JPEG_MAGIC = [0xff, 0xd8, 0xff]

export function looksLikeJpeg(bytes: Uint8Array): boolean {
  if (bytes.length < 4) return false
  return JPEG_MAGIC.every((byte, index) => bytes[index] === byte)
}

function reject(message: string): never {
  throw new AppError('bad_request', message, { fieldErrors: { photo: message } })
}

/**
 * Decodes, checks and re-encodes one photo. Declared limits are checked before
 * decoding so a decompression bomb is refused rather than expanded.
 */
export function sanitise(input: Uint8Array, limits: ImageLimits): SanitisedImage {
  if (input.byteLength === 0) reject('사진 파일이 비어 있습니다.')
  if (input.byteLength > limits.maxBytes) {
    reject(`사진 한 장은 ${Math.floor(limits.maxBytes / 1024)}KB 이하여야 합니다.`)
  }
  if (!looksLikeJpeg(input)) {
    reject('JPEG 사진만 올릴 수 있습니다. 브라우저에서 변환 후 다시 시도해 주세요.')
  }

  let raw: { width: number; height: number; data: Uint8Array }
  try {
    // maxMemoryUsageInMB bounds the decoder itself, so a crafted header cannot
    // make it allocate its way past the runtime's memory limit (MEDIA-03).
    raw = decode(input, { useTArray: true, maxMemoryUsageInMB: 192, maxResolutionInMP: 40 }) as {
      width: number
      height: number
      data: Uint8Array
    }
  } catch {
    reject('사진을 읽을 수 없습니다. 손상된 파일이거나 지원하지 않는 형식입니다.')
  }

  if (!raw.width || !raw.height) reject('사진 크기를 확인할 수 없습니다.')

  const megapixelsX100 = Math.round((raw.width * raw.height) / 10_000)
  if (megapixelsX100 > limits.maxMegapixelsX100) {
    reject(
      `사진 전체 화소가 너무 큽니다. ${(limits.maxMegapixelsX100 / 100).toFixed(2)}MP 이하로 줄여 주세요.`,
    )
  }
  if (Math.max(raw.width, raw.height) > limits.maxLongEdge * 2) {
    reject(`사진의 긴 변이 너무 깁니다. ${limits.maxLongEdge}px 이하로 줄여 주세요.`)
  }

  const target = fitWithin(raw.width, raw.height, limits.maxLongEdge)
  const fullPixels =
    target.width === raw.width && target.height === raw.height
      ? raw
      : resize(raw, target.width, target.height)

  // Step the quality down until the result fits the storage target, so one
  // noisy photo cannot consume a member's whole allowance.
  let quality = 82
  let full = encodeJpeg(fullPixels, quality)
  while (full.byteLength > limits.targetBytes && quality > 45) {
    quality -= 10
    full = encodeJpeg(fullPixels, quality)
  }

  const thumbSize = fitWithin(fullPixels.width, fullPixels.height, limits.thumbLongEdge)
  const thumb = encodeJpeg(resize(fullPixels, thumbSize.width, thumbSize.height), 72)

  return { full, thumb, width: fullPixels.width, height: fullPixels.height, quality }
}

