/**
 * Static asset serving for the single-page app.
 *
 * Two rules matter for the product:
 *   - Hashed build assets are cached hard; `index.html` never is, so a new
 *     release is picked up on the next load.
 *   - Any unknown non-API path falls back to `index.html`, which is what makes
 *     reloading a deep link such as /admin/settings land on that same screen
 *     instead of a 404.
 */
import { createReadStream, existsSync, statSync } from 'node:fs'
import { readFile } from 'node:fs/promises'
import path from 'node:path'
import { Readable } from 'node:stream'

const MIME: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.map': 'application/json; charset=utf-8',
  '.webmanifest': 'application/manifest+json',
  '.txt': 'text/plain; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8',
  '.mp4': 'video/mp4',
}

export interface StaticOptions {
  root: string
  /** Extra origins the page may talk to, e.g. a self-hosted AI endpoint. */
  connectSources?: string[]
}

export class StaticFiles {
  private readonly root: string
  private readonly indexPath: string
  private indexCache: { body: string; mtimeMs: number } | null = null

  constructor(private readonly options: StaticOptions) {
    this.root = path.resolve(options.root)
    this.indexPath = path.join(this.root, 'index.html')
  }

  get available(): boolean {
    return existsSync(this.indexPath)
  }

  /** Serves a file, or the SPA shell when the path is a client-side route. */
  async serve(request: Request, pathname: string): Promise<Response> {
    const resolved = this.resolve(pathname)
    // `/` resolves to index.html on disk, but the shell must still come back
    // with its security headers and no-store - so it always goes through
    // shell(), never the generic file path.
    if (resolved === this.indexPath) return this.shell(request)
    if (resolved) {
      const stat = statSync(resolved)
      const ext = path.extname(resolved).toLowerCase()
      const isHashed = /\/assets\/|-[0-9a-f]{8,}\./.test(resolved)
      const headers = new Headers({
        'content-type': MIME[ext] ?? 'application/octet-stream',
        'content-length': String(stat.size),
        'cache-control': isHashed ? 'public, max-age=31536000, immutable' : 'public, max-age=60',
        'x-content-type-options': 'nosniff',
      })
      if (request.method === 'HEAD') return new Response(null, { status: 200, headers })
      const stream = Readable.toWeb(createReadStream(resolved)) as ReadableStream
      return new Response(stream, { status: 200, headers })
    }
    return this.shell(request)
  }

  /** The SPA shell with the security headers the spec requires (SEC-03). */
  async shell(request: Request): Promise<Response> {
    if (!this.available) {
      return new Response(
        '<!doctype html><meta charset="utf-8"><title>yeopjari</title>' +
          '<p>웹 빌드가 없습니다. <code>npm run build -w @yeopjari/web</code>를 실행해 주세요.</p>',
        { status: 503, headers: { 'content-type': 'text/html; charset=utf-8' } },
      )
    }
    const stat = statSync(this.indexPath)
    if (!this.indexCache || this.indexCache.mtimeMs !== stat.mtimeMs) {
      this.indexCache = { body: await readFile(this.indexPath, 'utf8'), mtimeMs: stat.mtimeMs }
    }
    const headers = new Headers({
      'content-type': 'text/html; charset=utf-8',
      'cache-control': 'no-store',
      'content-security-policy': this.csp(),
      'x-content-type-options': 'nosniff',
      'referrer-policy': 'strict-origin-when-cross-origin',
      'x-frame-options': 'DENY',
      'permissions-policy': 'geolocation=(), camera=(), microphone=(), payment=()',
      'cross-origin-opener-policy': 'same-origin',
    })
    if (request.method === 'HEAD') return new Response(null, { status: 200, headers })
    return new Response(this.indexCache.body, { status: 200, headers })
  }

  private csp(): string {
    const connect = ["'self'", ...(this.options.connectSources ?? [])].join(' ')
    return [
      "default-src 'self'",
      "base-uri 'self'",
      "script-src 'self'",
      // Mantine injects a CSS-variable style block at runtime.
      "style-src 'self' 'unsafe-inline'",
      "img-src 'self' data: blob:",
      "font-src 'self' data:",
      `connect-src ${connect}`,
      "form-action 'self'",
      "frame-ancestors 'none'",
      "object-src 'none'",
      'upgrade-insecure-requests',
    ].join('; ')
  }

  /** Maps a URL path to a file inside the root, refusing traversal. */
  private resolve(pathname: string): string | null {
    let decoded: string
    try {
      decoded = decodeURIComponent(pathname)
    } catch {
      return null
    }
    if (decoded.includes('\0')) return null
    const candidate = path.resolve(this.root, `.${path.posix.normalize(decoded)}`)
    if (candidate !== this.root && !candidate.startsWith(this.root + path.sep)) return null
    if (!existsSync(candidate)) return null
    const stat = statSync(candidate)
    if (stat.isDirectory()) {
      const index = path.join(candidate, 'index.html')
      return existsSync(index) ? index : null
    }
    return stat.isFile() ? candidate : null
  }
import { describe, expect, it } from 'vitest'
import { isPrivateHost, normaliseWebsite } from '../util/url.js'
import { hasActiveSvgContent, sniffImage } from '../media/favicon.js'
import { mailboxKey } from '../util/text.js'

describe('normaliseWebsite', () => {
  it('keeps http(s) and reads a bare domain as https', () => {
    expect(normaliseWebsite('https://www.samsung.com')).toBe('https://www.samsung.com/')
    expect(normaliseWebsite('maum.ai')).toBe('https://maum.ai/')
    expect(normaliseWebsite('  http://example.co.kr/path ')).toBe('http://example.co.kr/path')
  })

  it('refuses anything that is not a web page', () => {
    for (const value of [
      'javascript:alert(1)',
      'JAVASCRIPT:alert(1)',
      'data:text/html,<script>alert(1)</script>',
      'vbscript:msgbox',
      'file:///etc/passwd',
      'ftp://example.com',
      'https://user:pass@example.com',
      'intranet',
    ]) {
      expect(normaliseWebsite(value), value).toBeNull()
    }
  })
})

describe('isPrivateHost', () => {
  it('flags loopback, private, link-local and metadata addresses', () => {
    for (const host of [
      'localhost', '127.0.0.1', '10.1.2.3', '172.16.0.1', '172.31.255.255', '192.168.0.1',
      '169.254.169.254', '100.64.0.1', '0.0.0.0', '[::1]', '::1', 'fd00::1', 'fe80::1',
      '::ffff:127.0.0.1', '::ffff:7f00:1', 'router.local', 'db.internal', 'printer.lan',
    ]) {
      expect(isPrivateHost(host), host).toBe(true)
    }
  })

  it('lets public hosts through', () => {
    for (const host of ['www.samsung.com', '8.8.8.8', '172.32.0.1', '2606:4700::1111', 'maum.ai']) {
      expect(isPrivateHost(host), host).toBe(false)
    }
  })

  it('sees through the forms a URL parser normalises', () => {
    // new URL turns these into dotted decimal before the check sees them.
    for (const raw of ['http://2130706433/', 'http://0x7f.0.0.1/', 'http://127.1/']) {
      expect(isPrivateHost(new URL(raw).hostname), raw).toBe(true)
    }
  })
